export function ReferenceLabel({name}: {name?: string}) {
  const [pcbX, pcbY] = offsets[name ?? ""] ?? [0, 2]
  return <silkscreentext text="{NAME}" layer="top" pcbX={pcbX} pcbY={pcbY}
    pcbRotation={360} anchorAlignment="center" fontSize={1} />
}
